CREATE PROCEDURE [dbo].[sp_toast_update_guest_counts_from_items_sold] AS /** ## Procedure Name       *[toast].[dbo].[sp_toast_update_guest_counts_from_items_sold]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20250625      ### Output    *describe the fields of the result set   (if code is in this description, block the code with three backticks on a blank line above and below the code block.   After the first tripple backtick, place the name of the language the code is written in.   See the example of this in the Parameters section above.  Follow the second tuple with a blank line.*      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Proc'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;  		declare @Params varchar(2000) = (select '' as params for json path)          update toast.dbo.cfg_menu_items set 			Guest_Count = try_cast(replace(j.name,'Guest Count ', '') as decimal(3,1)) 		from toast.dbo.cfg_menu_items i         cross apply             openjson(item_tags)             with (name varchar(75) '$.name') as j 		where j.name like 'Guest Count%'      	select 			hc.StoreNum, 			hc.dateofbusiness, 			hi.OrderID, 			sum(i.Guest_Count) Guests 		into #guestCounts 		from toast.dbo.hstItem hi 		join toast.dbo.hstOrder hc 		on hi.OrderID = hc.OrderID 		join toast.dbo.cfg_menu_items i 		on hi.MenuItemMLI = i.MultiLocationId         and hi.StoreNum = i.StoreNum 		where hi.deferred = 0         and hi.voided = 0         and hc.dateofbusiness >= convert(date,getdate()-14) 		group by hc.storenum, hc.dateofbusiness, hi.OrderID 		order by hc.StoreNum, hc.DateOfBusiness, hi.OrderID  		update toast.dbo.hstOrder set 			NumberOfGuests = 0;  		update toast.dbo.hstOrder set 			NumberOfGuests = gc.Guests  		from toast.dbo.hstOrder o 		join #guestCounts gc 		on o.OrderID = gc.OrderID  		drop table #guestCounts                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END